# Each dependsOnAny group requires at least one completed, qualified branch.
# Provider implementations are individually optional; selecting one requires all
# its ordinary prerequisites. Both alternatives remain included in total effort.
ALTERNATIVE_DEPENDENCIES = {
    'W-042': [['W-041', 'W-139']],
    'W-045': [['W-041', 'W-139']],
}
LAUNCH_SCOPES = {i: 'optional' for i in ('W-091', 'W-041', 'W-078', 'W-139', 'W-140', 'W-141', 'W-142', 'W-143')}

def main():
    scenarios=[]
    for line in SCENARIOS.strip().splitlines():
        i,title,given,when,then,inv=line.split('|')
        if i in ('AC-280', 'AC-299'):
            then += '; ' + D5_RUNTIME_CORPUS
        scenarios.append(dict(id=i,title=title,given=given,when=when,then=then,invariants=inv.split(',')))
    packages=[]
    for line in PACKAGES.strip().splitlines():
        i,m,title,owner,deps,days,paths,deliverable,accept=line.split('|')
        if i in ('W-141', 'W-143'):
            deliverable += '; ' + D5_RUNTIME_CORPUS
        lo,hi=map(int,days.split(':'))
        packages.append(dict(id=i,milestone=m,title=title,ownerRole=owner,dependsOn=deps.split(',') if deps else [],estimatedEngineeringDays={'low':lo,'high':hi},modules=paths.split(','),deliverable=deliverable,acceptance=accept.split(',')))
        if i in ALTERNATIVE_DEPENDENCIES:
            packages[-1]['dependsOnAny'] = ALTERNATIVE_DEPENDENCIES[i]
        if i in LAUNCH_SCOPES:
            packages[-1]['launchScope'] = LAUNCH_SCOPES[i]
    scenarios.sort(key=lambda item: int(item['id'].split('-')[1]))
    packages.sort(key=lambda item: int(item['id'].split('-')[1]))
    (ROOT/'acceptance.json').write_text(json.dumps({'schemaVersion':'1.0','scenarios':scenarios},indent=2)+'\n')
    (ROOT/'backlog.json').write_text(json.dumps({'schemaVersion':'1.0','packages':packages},indent=2)+'\n')
    lo=sum(p['estimatedEngineeringDays']['low'] for p in packages)
    hi=sum(p['estimatedEngineeringDays']['high'] for p in packages)
    blocks=[f'{len(packages)} work packages; estimated total {lo}–{hi} engineering-days before organization-specific access delays. At four full-time engineers and 70% effective delivery capacity, the arithmetic is roughly {lo/14:.0f}–{hi/14:.0f} weeks; dependency paths and integration findings may extend this. Re-estimate after M0.']
    for p in packages:
        alternatives = ''.join(' At least one qualified provider: ' + ' or '.join(group) + '.' for group in p.get('dependsOnAny', []))
        runtime_acceptance = ' ' + D5_RUNTIME_CORPUS if p['id'] in ('W-141', 'W-143') else ''
        blocks.append(f"### {p['id']} · {p['title']}\n\nMilestone {p['milestone']} · Owner: {p['ownerRole']} · Estimate: {p['estimatedEngineeringDays']['low']}–{p['estimatedEngineeringDays']['high']} engineering-days.\n\nDependencies: {', '.join(p['dependsOn']) or 'None'}.{alternatives} Modules: {', '.join(p['modules'])}.\n\nDeliverable: {p['deliverable']}.\n\nAcceptance: {', '.join(p['acceptance'])}.{runtime_acceptance}")
    path=ROOT/'14-build-backlog.md'; text=path.read_text()
    # Migrate the generated chapter introduction along with the package records.
    for old,new in {'Prove Claude restricted-pod/gateway and MCP effect-identity spikes;': 'Prove Claude restricted-pod/gateway and, if selecting MCP, its effect-identity spike;', 'Actual deployment MCP mapping, data setup, readiness, verification and expiry.': 'At least one qualified real provider: Argo PR previews or MCP; isolated data, readiness, verification and expiry.', 'W-091 alone is marked `launchScope: optional` and may remain deferred.': 'W-091 is optional forensics. W-041/W-078 (MCP) and W-139/W-140 (Argo) are individually optional provider branches, but W-042 and W-045 MUST complete at least one qualified branch. `dependsOn` lists mandatory prerequisites; every `dependsOnAny` group requires at least one completed alternative with conformance evidence. Selecting a branch requires all of its prerequisites; enabling both requires qualifying both. Static graph checks cover every possible branch, not runtime qualification.', 'The aggregate estimate includes its 2–4 days; omit that work if forensics remains deferred.': 'D5 packages W-141–W-143 are optional for human-mode launch but all are required before ai_only enablement. The aggregate estimate includes them, optional forensics and both provider alternatives; omit deferred forensics and the unselected provider branch when estimating implementation effort.'}.items():
        text=text.replace(old,new)
    text=text.replace('Warm pools and human-plan exemptions remain deferred.', 'Warm pools remain deferred. D5 replaces human review only through W-141–W-143; omission of plan approval remains excluded.')
    anchor='Enabling an earned capability still requires its own evidence and approvals.'
    addition=' W-141–W-143 are optional for human-mode launch and all are required before ai_only enablement, which is a joint human decision and is never earned automatically.'
    text=re.sub(re.escape(anchor)+'(?:'+re.escape(addition)+')*', lambda _: anchor+addition, text)
    text=text.replace('platform and documentation; mixed work. |', 'platform and documentation; mixed work; design-only delivery and build-from-design binding (W-144). |')
    anchor='The M3 pilot must label new-target creation unavailable until those capabilities are qualified.'
    addition=' W-144 adds the design-only delivery scope and build-from-design binding in human mode in M6, after W-072/W-073 peer review, W-080 PR follow-through and W-069 greenfield confirmation; W-059 requires it before launch, and W-141 (AC-319) owns the ai-review design templates.'
    # Migrate the earlier revision 1.13 draft sentence before normalizing the current one.
    text=text.replace(' W-144 adds the design-only delivery scope and build-from-design binding in M6, after W-072/W-073 peer review, W-080 PR follow-through and W-069 greenfield confirmation; W-059 requires it before launch.', '')
    text=re.sub(re.escape(anchor)+'(?:'+re.escape(addition)+')*', lambda _: anchor+addition, text)
    text=text.replace('The aggregate estimate includes its 2–4 days and both provider alternatives;', 'The aggregate estimate includes optional forensics, D5 packages and both provider alternatives;')
    start=text.index('<!-- BACKLOG_START -->')+len('<!-- BACKLOG_START -->'); end=text.index('<!-- BACKLOG_END -->')
    path.write_text(text[:start]+'\n\n'+'\n\n'.join(blocks)+'\n\n'+text[end:])
    appendix=['# Acceptance scenario catalogue','Each scenario is an implementation obligation. The specification package does not claim these product tests have run.']
    for s in scenarios:
        appendix.append(f"## {s['id']} · {s['title']}\n\nGiven: {s['given']}.\n\nWhen: {s['when']}.\n\nThen: {s['then']}.\n\nInvariants: {', '.join(s['invariants'])}.")
    (ROOT/'16-acceptance-catalogue.md').write_text('\n\n'.join(appendix)+'\n')
    print(f'Generated {len(packages)} packages, {len(scenarios)} acceptance scenarios, {lo}–{hi} engineering-days')

if __name__=='__main__': main()
